f4THpo.jpg","description":"2005년 유키무라 마코토의 만화로, 복수만 배운 소년이 칼이 필요 없는 땅을 상상하기까지의 작품.","editorial_intro":"복수만 배운 소년이 칼이 필요 없는 땅을 상상하기까지의 작품.","source":"Human review · AniList","canonical_key":"manga:빈란드사가:series","evidence_url":"https://anilist.co/manga/30642"},{"id":"reviewed:manga:플루토","external_id":"30745","title":"플루토","creator":"우라사와 나오키","release_year":2003,"media_type":"MANGA","poster_url":"https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30745-kueBpwriQkvZ.jpg","description":"2003년 우라사와 나오키의 만화로, 로봇의 죽음 앞에서 인간보다 선명한 슬픔과 증오를 발견하는 작품.","editorial_intro":"로봇의 죽음 앞에서 인간보다 선명한 슬픔과 증오를 발견하는 작품.","source":"Human review · AniList","canonical_key":"manga:플루토:series","evidence_url":"https://anilist.co/manga/30745"},{"id":"reviewed:manga:슬램덩크","external_id":"30051","title":"슬램덩크","creator":"이노우에 다케히코","release_year":1990,"media_type":"MANGA","poster_url":"https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30051-5KJyPlO7z5F4.png","description":"1990년 이노우에 다케히코의 만화로, 사랑 때문에 잡은 농구공이 한 불량학생의 세계를 팀의 크기로 넓히는 작품.","editorial_intro":"사랑 때문에 잡은 농구공이 한 불량학생의 세계를 팀의 크기로 넓히는 작품.","source":"Human review · AniList","canonical_key":"manga:슬램덩크:series","evidence_url":"https://anilist.co/manga/30051"},{"id":"reviewed:manga:nana","external_id":"30028","title":"NANA","creator":"야자와 아이","release_year":2000,"media_type":"MANGA","poster_url":"https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30028-VJqBC1ar6AxE.png","description":"2000년 야자와 아이의 만화로, 같은 이름으로 만난 두 여자가 사랑과 꿈의 다른 열차를 함께 타는 작품.","editorial_intro":"같은 이름으로 만난 두 여자가 사랑과 꿈의 다른 열차를 함께 타는 작품.","source":"Human review · AniList","canonical_key":"manga:nana:series","evidence_url":"https://anilist.co/manga/30028"},{"id":"reviewed:manga:불새","external_id":"31325","title":"불새","creator":"데즈카 오사무","release_year":1954,"media_type":"MANGA","poster_url":"https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx31325-n1n3iHr1K6xH.png","description":"1954년 데즈카 오사무의 만화로, 영원한 생명을 좇는 인간들을 시대마다 다시 태어나게 해 같은 욕망을 비추는 작품.","editorial_intro":"영원한 생명을 좇는 인간들을 시대마다 다시 태어나게 해 같은 욕망을 비추는 작품.","source":"Human review · AniList","canonical_key":"manga:불새:series","evidence_url":"https://anilist.co/manga/31325"},{"id":"reviewed:manga:데스노트","external_id":"30021","title":"데스노트","creator":"오바 쓰구미·오바타 다케시","release_year":2003,"media_type":"MANGA","poster_url":"https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30021-FE6kmrfpuKyb.jpg","description":"2003년 오바 쓰구미·오바타 다케시의 만화로, 죽음을 기록하는 공책을 두고 천재와 탐정이 정의의 얼굴을 서로 바꿔 쓰는 작품.","editorial_intro":"죽음을 기록하는 공책을 두고 천재와 탐정이 정의의 얼굴을 서로 바꿔 쓰는 작품.","source":"Human review · AniList","canonical_key":"manga:데스노트:series","evidence_url":"https://anilist.co/manga/30021"}]$catalog$::jsonb) as x(
    id text, external_id text, title text, creator text, release_year integer, media_type text,
    poster_url text, description text, editorial_intro text, source text, canonical_key text, evidence_url text
  )
), resolved as (
  select coalesce((
    select w.id from public.works w
    where upper(w.media_type)=i.media_type
      and w.release_year=i.release_year
      and regexp_replace(lower(w.title),'[^a-z0-9가-힣]+','','g')=regexp_replace(lower(i.title),'[^a-z0-9가-힣]+','','g')
    order by (w.catalog_status in ('verified','curated')) desc, w.created_at asc limit 1
  ), i.id) resolved_id, i.* from incoming i
)
insert into public.works (
  id,external_id,title,creator,release_year,media_type,poster_url,description,editorial_intro,source,canonical_key,
  catalog_status,metadata_verified_at,edition_verified,tags
)
select resolved_id,external_id,title,creator,release_year,media_type,poster_url,description,editorial_intro,source,canonical_key,
       'verified',now(),media_type in ('BOOK','MANGA'),'[]'::jsonb
from resolved
on conflict (id) do update set
  external_id=coalesce(excluded.external_id,public.works.external_id), title=excluded.title, creator=excluded.creator,
  release_year=excluded.release_year, media_type=excluded.media_type, poster_url=excluded.poster_url,
  description=excluded.description, editorial_intro=excluded.editorial_intro, source=excluded.source,
  canonical_key=excluded.canonical_key, catalog_status='verified', metadata_verified_at=now(),
  edition_verified=excluded.edition_verified, updated_at=now();

-- Keep duplicates for audit history, but remove them from recommendation eligibility.
update public.works candidate
set catalog_status='quarantined', updated_at=now()
where candidate.catalog_status='candidate'
  and exists (
    select 1 from public.works verified
    where verified.catalog_status='verified'
      and verified.id<>candidate.id
      and verified.canonical_key=candidate.canonical_key
  );
